const p = msg.payload || {};
const asBool = (v) => v === true || v === 'true' || v === 1 || v === '1';
const absDelta = Number(p.mq2AbsDelta) || 0;
const ready = asBool(p.mq2Ready);
let severity = 'normal';
const reasons = [];
if (asBool(p.flameDetected)) { severity = 'critical'; reasons.push('flame_detected'); }
if (!ready) { reasons.push('mq2_calibrating'); }
else if (absDelta >= 320) { severity = 'critical'; reasons.push('mq2_critical_delta'); }
else if (absDelta >= 180 && severity !== 'critical') { severity = 'warning'; reasons.push('mq2_warning_delta'); }
if (asBool(p.alarm) && severity === 'normal') { severity = 'warning'; reasons.push('local_alarm_latched'); }
if (asBool(p.pirMotion) && severity !== 'normal') { reasons.push('motion_context'); }
const reading = { ...p, receivedAt: new Date().toISOString(), mq2Ready: ready, severity, action: severity === 'normal' ? 'filter_local_only' : 'forward_to_cloud_or_dashboard', reasons };
const response = { ...msg, payload: { ok: true, receivedAt: reading.receivedAt, severity: reading.severity, action: reading.action, reasons: reading.reasons } };
return [severity === 'normal' ? { payload: reading } : null, severity !== 'normal' ? { payload: reading } : null, response];

const expectedToken = env.get('EDGE_SHARED_TOKEN');
const receivedToken = msg.req?.headers?.['x-edge-token'];
if (!expectedToken || receivedToken !== expectedToken) {
  return [null, { ...msg, statusCode: 401, payload: { ok: false, error: 'unauthorised edge event' } }];
}
const lambdaUrl = env.get('LAMBDA_FUNCTION_URL');
if (!lambdaUrl) {
  return [null, { ...msg, statusCode: 503, payload: { ok: false, error: 'LAMBDA_FUNCTION_URL is not configured' } }];
}
msg.payload = { ...msg.payload, nodeRedForwardedAt: new Date().toISOString(), nodeRedFlow: 'sit314-edge-flow' };
msg.url = lambdaUrl;
msg.headers = { 'content-type': 'application/json', 'x-edge-token': expectedToken };
return [msg, null];
